#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────
#
# Ads setup: everything Questura needs from Adsterra, saved to the owner's vault.
#
#   bash apps/questura/infra/ads/setup-ads.sh
#
# Collects the four banner unit codes (key + script address), an optional
# read-only stats token, and two owner decisions, then refreshes the Mac's
# live-content login. Values go to ~/.questura-vault/owner.env (mode 600);
# nothing is printed back. Claude reads them from there and wires the keys
# into apps/client/src/features/ads/lib/adUnits.ts. What ads do and why:
# apps/questura/docs/procedures/ads.md.
#
# Resumable: every finished stage is written to ~/.questura-vault/ads-progress.
# Re-run the same command and it offers to carry on from the first unfinished
# stage, redo any one stage, or start over. Stage ids, not numbers, are saved,
# so a newer version of this script still knows where you were.
#
# Written for macOS's bash 3.2: no associative arrays, no mapfile.

ENV_FILE="${QUESTURA_VAULT_ENV:-$HOME/.questura-vault/owner.env}"
PROGRESS_FILE="${ADS_WIZARD_PROGRESS:-$HOME/.questura-vault/ads-progress}"
REPO_ROOT=$(cd "$(dirname "$0")/../../../.." && pwd)
SITE_URL="https://www.questurian.com"
DASHBOARD="https://beta.publishers.adsterra.com"
STATS_API="https://api3.adsterratools.com/publisher"

for tool in curl grep sed; do
  command -v "$tool" >/dev/null || { echo "missing tool: $tool" >&2; exit 2; }
done

umask 077
mkdir -p "$(dirname "$ENV_FILE")" "$(dirname "$PROGRESS_FILE")"
touch "$ENV_FILE" "$PROGRESS_FILE"
chmod 600 "$ENV_FILE" "$PROGRESS_FILE"
WORK=$(mktemp -d); chmod 700 "$WORK"; trap 'rm -rf "$WORK"' EXIT

# vault NAME: the saved value, or nothing (a missing name is not an error).
vault() { { _existing "$1" || true; } | sed -e 's/^"//' -e 's/"$//'; }

# ── Resume bookkeeping ───────────────────────────────────────────────────

STAGE_IDS="account website unit-728x90 unit-320x50 unit-300x250 unit-160x600 stats-token decisions refresh-login handoff"
TOTAL_STAGES=0
for _id in $STAGE_IDS; do TOTAL_STAGES=$((TOTAL_STAGES + 1)); done

is_done()   { grep -qx "$1" "$PROGRESS_FILE"; }
mark_done() { is_done "$1" || printf '%s\n' "$1" >> "$PROGRESS_FILE"; }
unmark()    { local tmp; tmp=$(mktemp); grep -vx "$1" "$PROGRESS_FILE" > "$tmp" || true; mv "$tmp" "$PROGRESS_FILE"; }
stage_number() { local n=0 id; for id in $STAGE_IDS; do n=$((n + 1)); [[ "$id" == "$1" ]] && { echo "$n"; return; }; done; }
stage_id_at()  { local n=0 id; for id in $STAGE_IDS; do n=$((n + 1)); [[ "$n" == "$1" ]] && { echo "$id"; return; }; done; }

# A stage sets STOP_HERE=1 to end the run without marking itself done (waiting
# on Adsterra, say). The next run starts at it again.
STOP_HERE=0
# A stage sets NOT_DONE=1 when it could not finish but the rest can go on.
NOT_DONE=0

# ── Adsterra helpers ─────────────────────────────────────────────────────

# read_snippet: reads a pasted "Get code" snippet (several lines) or a bare
# key, into SNIPPET. A banner code ends itself (its atOptions, then the line
# that loads invoke.js); anything else ends at an empty line. Returns 1 when
# input ends with nothing pasted (Ctrl-D).
read_snippet() {
  local line
  SNIPPET=""
  printf '  %sPaste the whole code, then press Enter (twice if it waits):%s\n' "$BOLD" "$RESET"
  while IFS= read -r line; do
    if [[ -z "${line//[[:space:]]/}" ]]; then
      [[ -n "${SNIPPET//[[:space:]]/}" ]] && return 0
      continue
    fi
    SNIPPET="$SNIPPET$line"$'\n'
    [[ "$line" == *invoke.js* && "$SNIPPET" == *atOptions* ]] && return 0
    [[ "$SNIPPET" =~ ^[[:space:]]*[A-Za-z0-9]{16,64}[[:space:]]*$ ]] && return 0
  done
  [[ -n "${SNIPPET//[[:space:]]/}" ]]
}

# first_match REGEX GROUP: prints capture group GROUP of the match in SNIPPET.
# `|` is the sed delimiter because the patterns contain slashes.
first_match() {
  printf '%s' "$SNIPPET" | tr '\n' ' ' | sed -nE "s|.*$1.*|\\$2|p" | head -n1
}

# capture_unit LABEL WIDTH HEIGHT VAR: asks for one banner unit's code until it
# is a real WIDTHxHEIGHT banner, then saves its key (and the script address).
capture_unit() {
  local label="$1" width="$2" height="$3" var="$4" key w h host current
  current=$(vault "$var")
  if [[ -n "$current" ]]; then
    note "The vault already has $var."
    confirm "Replace it with a new code?" || return 0
  fi
  while true; do
    read_snippet || { printf '\n'; warn "Input ended. Nothing saved for $label; run again to carry on here."; exit 1; }
    if [[ "$SNIPPET" == *container-* || ( "$SNIPPET" == *invoke.js* && "$SNIPPET" != *atOptions* ) ]]; then
      warn "That is not a Banner code (Native Banner, Popunder or Social Bar?)."
      note "Make a Banner unit of $label and paste its code instead."
      continue
    fi
    key=$(first_match "['\"]key['\"][[:space:]]*:[[:space:]]*['\"]([A-Za-z0-9]+)['\"]" 1)
    [[ -z "$key" ]] && key=$(first_match "/([A-Za-z0-9]{16,64})/invoke\\.js" 1)
    if [[ -z "$key" && "$SNIPPET" =~ ^[[:space:]]*([A-Za-z0-9]{16,64})[[:space:]]*$ ]]; then
      key="${BASH_REMATCH[1]}"
    fi
    w=$(first_match "['\"]width['\"][[:space:]]*:[[:space:]]*([0-9]+)" 1)
    h=$(first_match "['\"]height['\"][[:space:]]*:[[:space:]]*([0-9]+)" 1)
    # Only the banner's own script line: a paste that also holds a Popunder or
    # Social Bar code must not hand over that code's host (2026-10-17: it did).
    host=$(first_match "src=['\"](https?:)?//([^/'\"]+)/[A-Za-z0-9]{16,64}/invoke\\.js" 2)
    if [[ ! "$key" =~ ^[A-Za-z0-9]{16,64}$ ]]; then
      warn "Couldn't find the unit key in that. Copy the whole code from \"Get code\" and try again."
      continue
    fi
    if [[ -n "$w" && -n "$h" && ( "$w" != "$width" || "$h" != "$height" ) ]]; then
      warn "That code is a ${w}x${h} banner, not $label. Paste the $label unit's code."
      continue
    fi
    break
  done
  write_env "$var" "$key"
  if [[ -n "$host" ]]; then
    local origin="https://$host" saved
    saved=$(vault ADSTERRA_SCRIPT_ORIGIN)
    if [[ -n "$saved" && "$saved" != "$origin" ]]; then
      warn "This code loads from $origin, the earlier ones from $saved."
      note "Keeping $saved. Claude will check both before wiring the keys in."
      write_env ADSTERRA_SCRIPT_ORIGIN_ALT "$origin"
    else
      write_env ADSTERRA_SCRIPT_ORIGIN "$origin"
    fi
  else
    note "No script address in that paste; a full \"Get code\" paste on another size will fill it in."
  fi
}

unit_stage() {
  local label="$1" width="$2" height="$3" var="$4" where="$5" made="${6:-}"
  stage "Banner unit $label"
  say "The $label banner: $where"
  open_url "$DASHBOARD/websites"
  if [[ -n "$made" ]]; then
    note "$made"
  else
    step "Websites page → the questurian.com row → the + (add ad unit) button. Pick exactly:"
    say "    Ad unit / format .......... Banner   (not Native Banner, Popunder, Social Bar, Smartlink)"
    say "    Size (Available Ad Unit) .. $label"
    step "Click ADD."
  fi
  step "Get code (on the questurian.com row, or \"View Code Scripts\" in Adsterra's email)"
  step "→ the $label unit → copy ALL of its code."
  note "The code looks like: <script> atOptions = { 'key' : '…', 'width' : $width, … } </script>"
  note "plus a second <script src=\"//…/invoke.js\"> line. Paste both lines."
  printf '\n'
  capture_unit "$label" "$width" "$height" "$var"
  pause
}

# ── Stages ───────────────────────────────────────────────────────────────

stage_account() {
  stage "Adsterra publisher account"
  say "Ads come from Adsterra. You need a free publisher account (you are the publisher)."
  if confirm "Do you already have an Adsterra PUBLISHER account?"; then pause; return; fi
  open_url "https://publishers.adsterra.com/signup"
  step "Choose Publisher (not Advertiser)."
  step "Fill in a login, password, how they can contact you, and how you want to be paid."
  step "Accepting Adsterra's Terms is your decision; read them before you tick the box."
  step "Open the confirmation email (check Promotions/Spam) and click CONFIRM EMAIL."
  printf '\n'
  if ! confirm "Account made and email confirmed?"; then
    note "No problem. Run the same command later and it starts here."
    STOP_HERE=1
  fi
}

stage_website() {
  stage "Add questurian.com and wait for approval"
  open_url "$DASHBOARD/websites"
  step "Websites → ADD WEBSITE. Fill the form exactly like this:"
  printf '\n'
  say "  Website / URL ............. $SITE_URL"
  say "  Category .................. Travel   (none? the closest general one, e.g. Lifestyle;"
  say "                                       never Adult, Gambling or Dating)"
  say "  Ad unit / format .......... Banner"
  say "  Size (Available Ad Unit) .. 728x90"
  say "  BOOST CPM ................. OFF      (on = Adsterra adds pop-ups and overlays)"
  say "  Adult content? ............ No"
  printf '\n'
  warn "Don't pick: Popunder, Social Bar, Native Banner, Smartlink / Direct Link,"
  note "  In-Page Push, Interstitial, or the 468x60 / 160x300 sizes. The site has no place for them."
  note "A field that isn't listed here? Send Claude a screenshot of the form before you pick."
  printf '\n'
  step "Click ADD (or SAVE). The status shows Pending until Adsterra reviews the site."
  note "Approval is usually quick and comes by email. Codes only work once the site is Approved."
  if ! confirm "Does the site show Approved now?"; then
    note "Run the same command once the approval email arrives; it starts here."
    STOP_HERE=1
  fi
}

stage_unit_728x90()  { unit_stage "728x90"  728 90  ADSTERRA_KEY_728X90  "the wide bar in articles and on homepages (desktop)." \
  "Made the 728x90 when you added the site? Then just get its code. If not, add it with the + on the questurian.com row (Banner, 728x90)."; }
stage_unit_320x50()  { unit_stage "320x50"  320 50  ADSTERRA_KEY_320X50  "the same bar on phones and narrow columns."; }
stage_unit_300x250() { unit_stage "300x250" 300 250 ADSTERRA_KEY_300X250 "the box in listicles, the rail and homepage Rectangle blocks."; }
stage_unit_160x600() { unit_stage "160x600" 160 600 ADSTERRA_KEY_160X600 "the tall ad in the side rail on big screens."; }

stage_stats_token() {
  stage "Stats token (optional, read-only)"
  say "Lets Claude check impressions and earnings per ad size after launch,"
  say "instead of you reading them off the dashboard. It cannot change anything."
  say "Press Enter with nothing pasted to skip."
  open_url "$DASHBOARD"
  step "Settings (or your profile menu) → the API tab → GENERATE NEW TOKEN."
  step "Copy the token right away: Adsterra hides it after the page reloads."
  printf '\n'
  ask_secret ADSTERRA_API_TOKEN "Paste the token (hidden):"
  if [[ -z "${ADSTERRA_API_TOKEN:-}" ]]; then
    note "Skipped. Re-run this stage later to add it."
    NOT_DONE=1
    pause
    return
  fi
  local code
  # Header from a file, so the token never shows in the process list.
  printf 'X-API-Key: %s\n' "$ADSTERRA_API_TOKEN" > "$WORK/stats-auth"
  code=$(curl -sS -o /dev/null -m 20 -w '%{http_code}' -H "@$WORK/stats-auth" \
    "$STATS_API/domains.json" || echo 000)
  rm -f "$WORK/stats-auth"
  case "$code" in
    200) printf '  %s✓ Adsterra accepted the token%s\n' "$GREEN" "$RESET" ;;
    401|403) warn "Adsterra refused that token ($code). Generate a new one and redo this stage."; NOT_DONE=1 ;;
    *) warn "Couldn't check the token (HTTP $code). Saving it anyway; Claude will retry." ;;
  esac
  if [[ "$code" != 401 && "$code" != 403 ]]; then write_env ADSTERRA_API_TOKEN "$ADSTERRA_API_TOKEN"; fi
  unset ADSTERRA_API_TOKEN
  pause
}

stage_decisions() {
  stage "Two decisions"
  say "1) Visitors in the EU and UK. Adsterra may set cookies to pick and count ads,"
  say "   and EU/UK law usually wants those visitors to agree first."
  step "a = ask EU/UK visitors before showing them ads (Claude builds the prompt)"
  step "b = no prompt for now"
  step "c = decide later (until then ads show to everyone, with no prompt)"
  local choice=""
  while [[ ! "$choice" =~ ^[abc]$ ]]; do
    printf '  %sYour choice [a/b/c]:%s ' "$BOLD" "$RESET"
    read -r choice || { printf '\n'; warn "Input ended; run again to carry on here."; exit 1; }
  done
  case "$choice" in a) write_env ADS_EU_CONSENT ask ;; b) write_env ADS_EU_CONSENT none ;; c) write_env ADS_EU_CONSENT later ;; esac
  printf '\n'
  say "2) Ads per listicle. Today: one after the intro, then one after every 2nd place."
  say "   A 19-place list gets 10 ads. Adsterra may turn down pages that look overloaded."
  ADS_LISTICLE_CAP=""
  while [[ ! "$ADS_LISTICLE_CAP" =~ ^[0-9]+$ ]]; do
    ask ADS_LISTICLE_CAP "Most ads on one listicle (6 suggested, 0 = no limit):"
    [[ -z "$ADS_LISTICLE_CAP" ]] && ADS_LISTICLE_CAP=6
  done
  write_env ADS_LISTICLE_CAP "$ADS_LISTICLE_CAP"
  pause
}

stage_refresh_login() {
  stage "Let your Mac copy the new ad table"
  say "Your Mac copies live content every 6 hours with a read-only login. The ad"
  say "block added a table that login can't read yet (nor the Eat/Stay/Itineraries"
  say "pages, from earlier). This re-creates the login with today's table list."
  note "It connects to the live database with the owner login already in your vault,"
  note "changes only that read-only login, and prints no passwords."
  printf '\n'
  if ! confirm "Run pnpm db:refresh:setup now?"; then
    SKIPPED+=("pnpm --dir apps/questura/apps/server db:refresh:setup")
    NOT_DONE=1
    return
  fi
  if pnpm --dir "$REPO_ROOT/apps/questura/apps/server" db:refresh:setup; then
    printf '  %s✓ done%s\n' "$GREEN" "$RESET"
  else
    printf '  %s✗ It stopped with an error (above). Redo this stage, or tell Claude what it said.%s\n' "$RED" "$RESET"
    SKIPPED+=("db:refresh:setup failed: redo stage $(stage_number refresh-login)")
    NOT_DONE=1
  fi
  pause
}

stage_handoff() {
  stage "Hand off to Claude"
  say "Saved in $ENV_FILE (values not shown):"
  local name
  for name in ADSTERRA_KEY_728X90 ADSTERRA_KEY_320X50 ADSTERRA_KEY_300X250 ADSTERRA_KEY_160X600 \
              ADSTERRA_SCRIPT_ORIGIN ADSTERRA_API_TOKEN ADS_EU_CONSENT ADS_LISTICLE_CAP; do
    if [[ -n "$(vault "$name")" ]]; then
      printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$name"
    else
      printf '  %s–%s %s %s(missing)%s\n' "$YELLOW" "$RESET" "$name" "$DIM" "$RESET"
    fi
  done
  printf '\n'
  say "Next, tell Claude:  \"the ads wizard is done\"."
  note "Claude puts the keys into the site, applies your two decisions, and opens a PR."
  note "Ads appear on the live site only when you merge that PR."
  pause "Press Enter to finish"
}

# ── Run ──────────────────────────────────────────────────────────────────

# paused ID: the run ends early; say where the next run picks up.
paused() {
  printf '\n%s%s  ⏸ Paused at stage %s/%s (%s)%s\n' "$BOLD" "$YELLOW" "$(stage_number "$1")" "$TOTAL_STAGES" "$1" "$RESET"
  (( ${#WRITTEN_ENV[@]} )) && note "saved this run: ${WRITTEN_ENV[*]}"
  note "Progress is saved. Run the same command again to carry on from here:"
  note "  bash apps/questura/infra/ads/setup-ads.sh"
  printf '\n'
}

# run_from N: runs stage N, then every later stage not already done.
run_from() {
  local start="$1" n=0 id fn
  for id in $STAGE_IDS; do
    n=$((n + 1))
    (( n < start )) && continue
    (( n > start )) && is_done "$id" && continue
    _STAGE_INDEX=$((n - 1))
    STOP_HERE=0; NOT_DONE=0
    fn="stage_${id//-/_}"
    "$fn"
    if (( STOP_HERE )); then paused "$id"; exit 0; fi
    if (( NOT_DONE )); then unmark "$id"; else mark_done "$id"; fi
  done
}

first_unfinished() {
  local n=0 id
  for id in $STAGE_IDS; do n=$((n + 1)); is_done "$id" || { echo "$n"; return; }; done
  echo 0
}

resume_menu() {
  _clear
  printf '\n%s%s  Adsterra ads setup%s\n\n' "$BOLD" "$BLUE" "$RESET"
  local n=0 id next
  next=$(first_unfinished)
  for id in $STAGE_IDS; do
    n=$((n + 1))
    if is_done "$id"; then printf '  %s✓%s %2s  %s\n' "$GREEN" "$RESET" "$n" "$id"
    elif [[ "$n" == "$next" ]]; then printf '  %s▸%s %2s  %s %s← next%s\n' "$BLUE" "$RESET" "$n" "$id" "$DIM" "$RESET"
    else printf '    %2s  %s\n' "$n" "$id"; fi
  done
  printf '\n'
  if [[ "$next" == 0 ]]; then
    note "Everything is done. Type a number to redo that stage, or press Enter to quit."
  else
    note "Enter = carry on at stage $next · a number = redo that stage · r = start over · q = quit"
  fi
  local reply=""
  printf '  %s>%s ' "$BOLD" "$RESET"; read -r reply || true
  case "$reply" in
    "") [[ "$next" == 0 ]] && exit 0; run_from "$next" ;;
    q|Q) exit 0 ;;
    r|R) : > "$PROGRESS_FILE"; note "Starting over. Saved values are kept: Enter keeps each one."; pause; run_from 1 ;;
    *)
      if [[ "$reply" =~ ^[0-9]+$ ]] && (( reply >= 1 && reply <= TOTAL_STAGES )); then
        unmark "$(stage_id_at "$reply")"; run_from "$reply"
      else
        warn "Not a choice: $reply"; exit 1
      fi ;;
  esac
}

if [[ -s "$PROGRESS_FILE" ]]; then
  resume_menu
else
  banner "Adsterra ads setup"
  run_from 1
fi

finish

# Name what is still open, so "complete" never hides a skipped stage.
left=""
for _id in $STAGE_IDS; do is_done "$_id" || left="$left $(stage_number "$_id"):$_id"; done
if [[ -n "$left" ]]; then
  warn "Not finished yet:$left"
  note "Run again to do them: bash apps/questura/infra/ads/setup-ads.sh"
  printf '\n'
fi
